module dma_controller_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg req1;
    reg req2;
    reg reset;
    wire grant1;
    wire grant2;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    dma_controller dut (
        .clk(clk),
        .req1(req1),
        .req2(req2),
        .reset(reset),
        .grant1(grant1),
        .grant2(grant2)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            req1 = 0;
            req2 = 0;
            repeat(2) @(posedge clk);
            #1 reset = 0;
            @(posedge clk);
            #1;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("\nTestcase %0d: Idle State Check", test_num);
            reset_dut();

            repeat(2) @(posedge clk);
            #1 #1;
 check_outputs(0, 0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("\nTestcase %0d: Channel 1 Single Request", test_num);
            reset_dut();
            req1 = 1;
            req2 = 0;
            @(posedge clk);
            #1 #1;
 check_outputs(1, 0);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("\nTestcase %0d: Channel 2 Single Request", test_num);
            reset_dut();
            req1 = 0;
            req2 = 1;
            @(posedge clk);
            #1 #1;
 check_outputs(0, 1);
        end
        endtask

    task testcase004;

        begin
            test_num = 4;
            $display("\nTestcase %0d: Simultaneous Requests - Priority Ch1", test_num);
            reset_dut();
            req1 = 1;
            req2 = 1;
            @(posedge clk);
            #1 #1;
 check_outputs(1, 0);
        end
        endtask

    task testcase005;

        begin
            test_num = 5;
            $display("\nTestcase %0d: Round-Robin Rotation (Ch1 -> Ch2)", test_num);
            reset_dut();
            req1 = 1;
            req2 = 1;
            @(posedge clk);
            @(posedge clk);
            #1 #1;
 check_outputs(0, 1);
        end
        endtask

    task testcase006;

        begin
            test_num = 6;
            $display("\nTestcase %0d: Full Cycle Rotation (Ch1 -> Ch2 -> Ch1)", test_num);
            reset_dut();
            req1 = 1;
            req2 = 1;
            @(posedge clk);
            @(posedge clk);
            @(posedge clk);
            #1 #1;
 check_outputs(1, 0);
        end
        endtask

    task testcase007;

        begin
            test_num = 7;
            $display("\nTestcase %0d: Request Withdrawal", test_num);
            reset_dut();
            req1 = 1;
            req2 = 1;
            @(posedge clk);
            req1 = 0;
            @(posedge clk);
            @(posedge clk);
            #1 #1;
 check_outputs(0, 1);
        end
        endtask

    task testcase008;

        begin
            test_num = 8;
            $display("\nTestcase %0d: Ch2 served first, then Ch1 joins", test_num);
            reset_dut();
            req2 = 1;
            @(posedge clk);
            req1 = 1;
            @(posedge clk);
            #1 #1;
 check_outputs(1, 0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("dma_controller Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_grant1;
        input expected_grant2;
        begin
            if (expected_grant1 === (expected_grant1 ^ grant1 ^ expected_grant1) &&
                expected_grant2 === (expected_grant2 ^ grant2 ^ expected_grant2)) begin
                $display("PASS");
                $display("  Outputs: grant1=%b, grant2=%b",
                         grant1, grant2);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: grant1=%b, grant2=%b",
                         expected_grant1, expected_grant2);
                $display("  Got:      grant1=%b, grant2=%b",
                         grant1, grant2);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, req1, req2, reset, grant1, grant2);
    end

endmodule

